ctx.imageSmoothingEnabled = false;
function resize(){
  let s = Math.min(innerWidth / W, innerHeight / H);
  if (s >= 1) s = Math.floor(s);            // integer scaling when possible
  cv.style.width  = Math.round(W*s) + 'px';
  cv.style.height = Math.round(H*s) + 'px';
}
addEventListener('resize', resize); resize();

// ---------- small helpers ----------
const clamp=(v,a,b)=>v<a?a:(v>b?b:v);
const lerp=(a,b,t)=>a+(b-a)*t;
const rnd=(a,b)=>a+Math.random()*(b-a);
function hex2rgb(h){return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)];}
function shade(h,f){const c=hex2rgb(h);return 'rgb('+c.map(v=>clamp(Math.round(v*f),0,255)).join(',')+')';}
function aabb(ax,ay,aw,ah,bx,by,bw,bh){return ax<bx+bw&&bx<ax+aw&&ay<by+bh&&by<ay+ah;}

// ---------- pixel font (5x7) ----------
const FONT={
