'8':[14,17,17,14,17,17,14],'9':[14,17,17,15,1,2,12],
'!':[4,4,4,4,4,0,4],'.':[0,0,0,0,0,0,4],'-':[0,0,0,14,0,0,0],':':[0,0,4,0,0,4,0],'%':[25,2,4,8,19,0,0],
' ':[0,0,0,0,0,0,0]
