function textW(s,scale){return s.length*6*scale-scale;}
function drawText(s,x,y,color,scale){
  scale=scale||1;
  ctx.fillStyle=color;
  let cx=x;
  for(let i=0;i<s.length;i++){
    const g=FONT[s[i]];
    if(g){ for(let r=0;r<7;r++){ const bits=g[r];
      for(let c=0;c<5;c++){ if(bits&(16>>c)) ctx.fillRect(cx+c*scale,y+r*scale,scale,scale); } } }
    cx+=6*scale;
  }
}
function centerText(s,y,color,scale){ drawText(s,Math.round(112-textW(s,scale)/2),y,color,scale); }

// ---------- sprites (16x16 pixel art, 2 flap frames each) ----------
function makeSprite(rows,pal){
  const c=document.createElement('canvas'); c.width=16; c.height=16;
  const g=c.getContext('2d');
  for(let y=0;y<16;y++) for(let x=0;x<16;x++){
    const ch=rows[y][x];
    if(ch!=='.'&&pal[ch]){ g.fillStyle=pal[ch]; g.fillRect(x,y,1,1); }
  }
  return c;
}
const PAL_P={G:'#22dd22',Y:'#ffee55',W:'#ffffff'};
const PAL_R={G:'#ff3333',Y:'#ffee55',W:'#ffffff'};
const PAL_Z={B:'#3355ff',Y:'#ffdd33'};
const PAL_G={R:'#ff3333',Y:'#ffee55',W:'#ffffff'};
const PAL_B={G:'#22dd22',Y:'#ffee55',W:'#ffffff'};
const PAL_BP={G:'#5566ff',Y:'#ffdd33',W:'#ffffff'};

const SPR={
player:[makeSprite([
".......GG.......",".......GG.......",".......GG.......",".......GG.......",".......GGY......",
"...G..GGY..G....","...G.GGGGG.G....","..GGGGGGGGGGGG..","..GGGGGGGGGGGG..",".GGGGGGGGGGGGGG.",
".GGGGGGGGGGGGGG.","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW"],PAL_P),
makeSprite([
".......GG.......",".......GG.......",".......GG.......",".......GG.......",".......GGY......",
"...G..GGY..G....","...G.GGGGG.G....","..GGGGGGGGGGGG..","..GGGGGGGGGGGG..",".GGGGGGGGGGGGGG.",
".GGGGGGGGGGGGGG.","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW"],PAL_P)],
captured:[makeSprite([
".......GG.......",".......GG.......",".......GG.......",".......GG.......",".......GGY......",
"...G..GGY..G....","...G.GGGGG.G....","..GGGGGGGGGGGG..","..GGGGGGGGGGGG..",".GGGGGGGGGGGGGG.",
".GGGGGGGGGGGGGG.","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW"],PAL_R),
makeSprite([
".......GG.......",".......GG.......",".......GG.......",".......GG.......",".......GGY......",
"...G..GGY..G....","...G.GGGGG.G....","..GGGGGGGGGGGG..","..GGGGGGGGGGGG..",".GGGGGGGGGGGGGG.",
".GGGGGGGGGGGGGG.","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW","WGGGGGGGGGGGGGGW"],PAL_R)],
zako:[makeSprite([
".......BB.......","......BBBB......","..YY..BBBB..YY..","..YYYYBBBBYYYY..","..YYYYBBBBBYYYY.",
"..YYYYBBBBBYYYY.","..YY..BBBB..YY..",".......BB.......",".......BB.......",".......BBY......",
".......BB.......",".......BB.......",".......BB.......",".......BB.......",".......BB.......",".......BB......."],PAL_Z),
makeSprite([
"..YY........YY..","..YYYY......YYYY","..YY..BBBB..YY..","......BBBB......",".......BB.......",
".......BB.......",".......BB.......",".......BB.......",".......BB.......",".......BBY......",
".......BB.......",".......BB.......",".......BB.......",".......BB.......",".......BB.......",".......BB......."],PAL_Z)],
goei:[makeSprite([
".......RR.......","......RRRR......","..RR..RRRR..RR..","..RRR.RRRR.RRR..","..RRRRRRRRRRRR..",
"..RRRRRRRRRRRR..","...RR.RRRR.RR...",".......RR.......",".......RR.......",".......RRY......",
".......RR.......",".......RR.......",".......RR.......",".......RR.......",".......RR.......",".......RR......."],PAL_G),
makeSprite([
