"..GGYGGGGGGYGG..","...GGGGGGGGGG...","....GGGGGGGG....","...GGGGGGGGGG...","..GGGGGGGGGGGG..",
"..GGGGGGGGGGGG..","...GGGGGGGGGG...",".......GG.......",".......GG.......",".......GG.......",".......GG......."],PAL_B),
makeSprite([
