  }
}
function drawHUD(){
  drawText('1UP',26,4,'#ffffff');
  drawText(String(G.score).padStart(6,'0'),24,12,'#ffffff');
  centerText('HIGH SCORE',4,'#ffffff');
  centerText(String(G.high).padStart(6,'0'),12,'#ffffff');
